import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"缓存与异步","description":"","frontmatter":{},"headers":[],"relativePath":"backend/caching.md","filePath":"backend/caching.md","lastUpdated":1794049926000}`),a={name:`backend/caching.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="缓存与异步" tabindex="-1">缓存与异步 <a class="header-anchor" href="#缓存与异步" aria-label="Permalink to “缓存与异步”">​</a></h1><p>本页说明缓存接口、缓存时长与失效、缓存管理，以及定时作业、后台循环、日志队列、发件箱与提交后推送等异步机制，适用于后端开发者。</p><h2 id="缓存" tabindex="-1">缓存 <a class="header-anchor" href="#缓存" aria-label="Permalink to “缓存”">​</a></h2><h3 id="缓存接口" tabindex="-1">缓存接口 <a class="header-anchor" href="#缓存接口" aria-label="Permalink to “缓存接口”">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>来源</th><th>用途</th></tr></thead><tbody><tr><td><code>ISharedCache</code></td><td>框架 <code>Caching.Abstractions</code></td><td>跨实例共享的缓存，各包都用它：授权规则、角色指派、会话门禁、验证码与登录节流、套餐白名单、打印模板等</td></tr><tr><td><code>ICache</code></td><td>框架</td><td>类型化缓存；配了 Redis 时是本机 L1 + Redis L2</td></tr><tr><td><code>ICacheStore</code></td><td>框架</td><td>字节存储，供分布式锁与幂等去重</td></tr></tbody></table><p>不配 Redis 时是 Full Profile 的进程内实现（<code>XiHan:Caching:InMemory</code>）：零外部依赖，单实例部署即可。多实例时各实例的缓存不共享，写入方的即时失效只对本实例生效，其他实例最迟按缓存时长过期。</p><p>配了 Redis（绑定 <code>cache</code> 或 <code>XiHan:Caching:Redis:Configuration</code>，见<a href="./../configuration#分布式缓存与消息">配置参考</a>），宿主装上 <code>Caching.Redis</code> 与 <code>Caching.Hybrid</code>：<code>ISharedCache</code>、字节存储与分布式锁走 Redis，失效对所有实例生效；<code>ICache</code> 的写入经 Redis 频道失效各实例的 L1。Redis 连不上时启动即失败。</p><p>进程内实现直接存对象引用，Redis 下值要序列化。所以缓存的值要能按 JSON 往返，取回的对象不要原地修改；Access 等包把缓存值存成 JSON 字符串，新写的缓存照此做。</p><h3 id="缓存时长与失效" tabindex="-1">缓存时长与失效 <a class="header-anchor" href="#缓存时长与失效" aria-label="Permalink to “缓存时长与失效”">​</a></h3><table tabindex="0"><thead><tr><th>数据</th><th>时长</th><th>失效</th></tr></thead><tbody><tr><td>会话门禁</td><td><code>BasicApp:Auth:SessionCacheSeconds</code>（30 秒）</td><td>注销、吊销、改密、锁屏、解锁、结束模仿时</td></tr><tr><td>套餐白名单（按租户）</td><td>30 秒</td><td>换套餐、改白名单时</td></tr><tr><td>权限规则、角色指派、继承图、委托、权限条件</td><td>60 秒</td><td>写入方即时失效</td></tr><tr><td>访问策略、字段安全规则、约束规则（按侧）</td><td>60 秒</td><td>写入方即时失效</td></tr><tr><td>打印模板（按侧 × 编码）</td><td>30 分钟</td><td>模板写入时</td></tr><tr><td>租户目录、权限授予</td><td>框架进程内缓存，<code>XiHan:MultiTenancy:Database:CacheTimeToLiveSeconds</code> / <code>XiHan:Security:Database:CacheTimeToLiveSeconds</code>（30 秒）</td><td>框架 <code>TenantRecordStore</code> / <code>PermissionGrantRecordStore</code> 写入时失效本实例的条目</td></tr></tbody></table><p>授予与指派的生效、到期在判定时按当前时间比较，不依赖缓存重建。</p><p>上面这些读穿缓存未命中时，经 <code>Runtime.Persistence.StoreScope</code> 在独立的只读工作单元里读库，看不到调用里还没提交的写入。所以写入方在调用里失效要用 <code>CacheInvalidation.RemoveAsync</code> / <code>RemoveManyAsync</code>（Runtime）：调用里只记下，由 Transaction 阶段开头的 <code>CacheInvalidationMiddleware</code> 在工作单元提交或回滚之后才删键（回滚了照样删，多失效一次只是多读一次库；同一缓存的键一次往返）。管道之外（种子、作业）调用即刻删除。</p><div class="warning custom-block"><p class="custom-block-title">不要在提交前删键</p><p>直接调 <code>cache.RemoveAsync</code> 会在提交之前删键。同一请求里的后续读取或并发请求在删键与提交之间未命中，会把提交前的旧数据写回缓存，变更要等缓存过期才生效。新写的读穿缓存一律经 <code>CacheInvalidation</code> 失效。</p></div><h3 id="命名空间与缓存管理" tabindex="-1">命名空间与缓存管理 <a class="header-anchor" href="#命名空间与缓存管理" aria-label="Permalink to “命名空间与缓存管理”">​</a></h3><p>每个包用 <code>AddCacheNamespace(包名, editable)</code> 登记键前缀 <code>&lt;包名&gt;:</code>。缓存管理只开放登记过的前缀，框架自己的键（如分布式锁）不出现：</p><table tabindex="0"><thead><tr><th>命名空间</th><th>能否改写值</th></tr></thead><tbody><tr><td><code>access:</code>、<code>identity:</code>、<code>tenancy:</code>、<code>openplatform:</code></td><td>否（鉴权、签名与套餐门控相关）</td></tr><tr><td><code>ai:</code></td><td>否（提供商目录的戳键）</td></tr><tr><td><code>realtime:</code>（配了 Redis 时才有）</td><td>否（在线状态）</td></tr><tr><td><code>notification:</code>、<code>printing:</code></td><td>是</td></tr></tbody></table><p>不可改写的命名空间仍可删除，删除后缓存按需重建。</p><p>缓存管理在 Maintenance 包，权限码只在平台一侧：</p><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>caches.namespaces</code></td><td><code>maintenance.caches.read</code></td><td>已登记的命名空间</td></tr><tr><td><code>caches.keys</code></td><td><code>maintenance.caches.read</code></td><td>按前缀列键，按续页标记（<code>continuation</code>）往下翻</td></tr><tr><td><code>caches.inspect</code></td><td><code>maintenance.caches.read</code></td><td>查看值、类型与剩余存活</td></tr><tr><td><code>caches.update</code></td><td><code>maintenance.caches.update</code></td><td>改写值，保留原到期时间；只对可改写的命名空间</td></tr><tr><td><code>caches.delete</code> / <code>caches.delete-by-prefix</code></td><td><code>maintenance.caches.delete</code></td><td>按键或按前缀删除</td></tr></tbody></table><p>进程内模式下对象缓存与字节存储是两张表，<code>caches.keys</code> 两层合起来列（先对象缓存、再字节存储），每个键标出所在的层。Redis 下只有一层，列键是 SCAN：一段可能一个键都没有，<code>caches.keys</code> 在操作里接着列到攒满一页（扫空一段提示值加倍，最多 100 次往返）；同一个键可能出现在两页，同一页内去重。</p><h2 id="异步与后台工作" tabindex="-1">异步与后台工作 <a class="header-anchor" href="#异步与后台工作" aria-label="Permalink to “异步与后台工作”">​</a></h2><p>BasicApp 没有自建的后台任务框架，异步工作分下面几类：</p><table tabindex="0"><thead><tr><th>类型</th><th>机制</th><th>例子</th></tr></thead><tbody><tr><td>定时作业</td><td>框架 <code>Scheduling.Database</code>：Feature 里 <code>AddJob&lt;T&gt;(名称, 计划)</code> 代码登记；运行时作业经 Maintenance 的作业管理登记</td><td>见下表</td></tr><tr><td>后台循环</td><td><code>IHostedFeature</code> 随应用启停</td><td>Notification 的发送循环与 Telegram 机器人；Auditing 的日志批量写入；Files 的导出执行；Realtime 的在线状态心跳（配了 Redis 时）</td></tr><tr><td>有界队列</td><td>调用里只入队，后台批量落库</td><td>七类分表日志（<code>BasicApp:Auditing:QueueCapacity</code> / <code>BatchSize</code> / <code>FlushIntervalSeconds</code>）；操作日志走框架的 <code>XiHan:Auditing:Database</code> 队列</td></tr><tr><td>提交后推送</td><td><code>IRealtimePush.SendAsync</code> 在调用里暂存，<code>RealtimeDispatchMiddleware</code> 在调用成功、事务提交之后发出</td><td><code>ForceLogout</code>、<code>ReceiveNotification</code>、<code>TaskProgress</code></td></tr><tr><td>提交后失效</td><td><code>CacheInvalidation</code> 暂存，<code>CacheInvalidationMiddleware</code> 在工作单元结束后删键</td><td>Access 的授权类缓存、会话门禁、套餐白名单</td></tr><tr><td>领域事件</td><td>发件箱随业务写入同一事务，后台投递给订阅方</td><td>见<a href="./entity#领域事件">实体基类</a></td></tr></tbody></table><p>不落库的瞬时推送（正在输入、助手的流式增量）用 <code>IRealtimePush.SendNowAsync</code>，只能在事务之外调用。</p><p>代码登记的作业：</p><table tabindex="0"><thead><tr><th>作业</th><th>计划（cron，UTC）</th><th>做什么</th></tr></thead><tbody><tr><td><code>auditing.retention</code></td><td><code>BasicApp:Auditing:RetentionCron</code>（缺省 <code>0 3 * * *</code>）</td><td>按保留天数清理日志，见<a href="./logging">日志审计</a></td></tr><tr><td><code>chat.messages.cleanup</code></td><td><code>0 4 * * *</code></td><td>按保留期清理聊天消息，见<a href="./chat">在线聊天</a></td></tr><tr><td><code>tenancy.tenants.expire</code></td><td><code>*/5 * * * *</code></td><td>把已过到期时间的租户标为到期，并停用租户目录里的记录</td></tr><tr><td><code>files.uploads.expire</code></td><td><code>15 * * * *</code></td><td>清理过期的分片上传</td></tr><tr><td><code>files.temporary.purge</code></td><td><code>45 * * * *</code></td><td>清理到期的临时文件，见<a href="./file#临时文件">文件与存储</a></td></tr><tr><td><code>openplatform.oauth-cleanup</code></td><td><code>30 3 * * *</code></td><td>物理删除过期一天的授权码与过期七天的令牌</td></tr></tbody></table><p>作业的查看、暂停、立即执行与改计划见<a href="./scheduling">定时任务</a>。</p><h3 id="发件箱" tabindex="-1">发件箱 <a class="header-anchor" href="#发件箱" aria-label="Permalink to “发件箱”">​</a></h3><ul><li>宿主装了框架的 <code>OutboxFeature</code>：领域事件先随业务事务落表 <code>outbox_message</code>，再由后台投递到消息代理（<code>XiHan:Messaging:Outbox</code>）。没配 RabbitMQ 时是进程内消息，配了即经 RabbitMQ 投递。</li><li>邮件、短信与机器人消息的待发送记录是应用表（<code>SysEmail</code>、<code>SysSms</code>、<code>SysBotMessage</code>），本身就是可查询、可重发的发件箱。别的包经 Contracts 的 <code>IMessageSender</code> 排队邮件与短信（模板不存在、渲染失败或没有可用配置即失败，不写记录）。</li><li>发送循环按 <code>BasicApp:Notification:DispatchInterval</code> 轮询（有新记录时提前唤醒），用条件更新领取记录，多实例只有一个能领到；失败第 n 次后等 n 倍 <code>RetryDelay</code>，至多 <code>MaxAttempts</code> 次。启动时把发送中超过 <code>StuckAfter</code> 的记录改回排队中。</li></ul><h3 id="导出" tabindex="-1">导出 <a class="header-anchor" href="#导出" aria-label="Permalink to “导出”">​</a></h3><p>导出任务（<code>export-tasks.submit</code>）进进程内队列，后台以发起人的凭据逐页调用对应的列表操作（权限、租户、数据范围与字段安全照常生效），生成 CSV / XLSX 存成 7 天的临时文件，进度经 <code>TaskProgress</code> 推送。见<a href="./file#导出中心">文件与存储</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./scheduling">定时任务</a> · <a href="./messaging">消息通知</a> · <a href="./realtime">实时推送</a></li></ul>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};